#include <bits/stdc++.h>
using namespace std;

static inline char comp_base(char c) {
    switch (c) {
        case 'A': return 'T';
        case 'C': return 'G';
        case 'G': return 'C';
        case 'T': return 'A';
        case 'U': return 'A';
        case 'M': return 'K';
        case 'R': return 'Y';
        case 'W': return 'W';
        case 'S': return 'S';
        case 'Y': return 'R';
        case 'K': return 'M';
        case 'V': return 'B';
        case 'H': return 'D';
        case 'D': return 'H';
        case 'B': return 'V';
        case 'N': return 'N';
        default:  return c;
    }
}

int main(int argc, char* argv[]) {
    (void)argc;
    (void)argv;

    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line;
    string header;
    string seq;
    bool have_seq = false;

    auto flush_record = [&]() {
        if (!have_seq) return;
        string rc;
        rc.resize(seq.size());
        for (size_t i = 0, j = seq.size(); i < seq.size(); ++i) {
            rc[i] = comp_base(seq[--j]);
        }
        cout << header << '\n';
        const size_t width = 60;
        for (size_t i = 0; i < rc.size(); i += width) {
            cout.write(rc.data() + i, min(width, rc.size() - i));
            cout.put('\n');
        }
    };

    while (getline(cin, line)) {
        if (!line.empty() && line[0] == '>') {
            flush_record();
            header = line;
            seq.clear();
            have_seq = true;
        } else {
            for (char c : line) {
                if (!isspace(static_cast<unsigned char>(c))) seq.push_back(c);
            }
        }
    }
    flush_record();

    return 0;
}

